package net.minecraft.client.gui.components;import net.minecraft.client.gui.Font;import net.minecraft.network.chat.Component;import java.util.function.Consumer;public class EditBox extends AbstractWidget {private String value="";private Consumer<String> responder=s->{};public EditBox(Font f,int x,int y,int w,int h,Component c){}public void setMaxLength(int n){}public void setValue(String s){value=s;responder.accept(s);}public String getValue(){return value;}public void setResponder(Consumer<String> c){responder=c;}}